// @generated by qw-codegen (crud)
// storage.config (generated CRUD; see docs/design-notes.md#codegen, #api-envelope): list filters/sort/paging, get, create, update, delete,
// batch delete, enabled toggle;
// 403 per permission, 400 translated, 409 duplicate, 404 unknown ids, @Idempotent, @ActionLog rows,
// Swagger. Hand-edited (module G): bodies are the whole driver form (here the local driver); the S3
// driver, SecretBox, SSRF refusals, test connection and the primary switch are in storage.e2e (config).
import type { NestExpressApplication } from '@nestjs/platform-express'
import { Test } from '@nestjs/testing'
import { getDataSourceToken } from '@nestjs/typeorm'
import { configPerms, Err, STORAGE_SECRET_MASK } from '@qiwu/shared'
import { I18nService } from 'nestjs-i18n'
import request from 'supertest'
import type { DataSource } from 'typeorm'
import { AppModule } from '../../src/app.module.js'
import { setupApp } from '../../src/app.setup.js'
import { SecretBox } from '../../src/core/crypto/secret-box.js'
import { REDIS, type Redis } from '../../src/core/redis/redis.module.js'
