const PREFIX = 'e2e-config-'
const URL = '/api/storage/configs'
const MISSING = 999_999
/** the form's fields, as the edit form sends them back */
const FORM = ['name', 'driver', 'publicPrefix', 'enabled', 'note']

let app: NestExpressApplication
let ds: DataSource
let redis: Redis
let i18n: I18nService
const tokens: Record<'admin' | 'reader' | 'plain', string> = { admin: '', reader: '', plain: '' }
const userIds: number[] = []
let roleId: number
/** the table's last id before this spec: every row above it is this spec's (cleanup) */
let lastId = 0

const call = (
  who: keyof typeof tokens,
  method: 'get' | 'post' | 'put' | 'delete',
  path = '',
  body?: object,
) => {
  const req = request(app.getHttpServer())[method](`${URL}${path}`).set(bearer(tokens[who]))
  return body ? req.send(body) : req
}
const create = (body: object) => call('admin', 'post', '', body)
/** A row added through the API, as POST answers it. */
const add = async (body: object) => (await create(body).expect(201)).body.data
let seq = 0
const unique = () => `${PREFIX}${++seq}`
/** A valid POST body made of `tag` (required and unique fields, the configured examples). */
const body = (tag: string, over: object = {}) => ({
  name: tag,
  driver: 'local',
  publicPrefix: null,
  ...over,
})
/** A translated message (the app's own translations). */
const t = (lang: string, key: string, args?: object) => i18n.t(key, { lang, args }) as string
const label = (lang: string, field: string) => t(lang, `field.storage.config.${field}`)
/** Live rows of the table (a list's total without filters). */
const count = async () =>
  Number((await ds.query('SELECT COUNT(*) AS n FROM fs_storage WHERE deleted_at IS NULL'))[0].n)
const idsOf = (res: request.Response) => res.body.data.items.map((r: { id: number }) => r.id)

async function user(name: string, roles: number[]) {
  const id = await insertRow(ds.manager, 'iam_user', {
    username: PREFIX + name,
    display_name: name,
    password_hash: 'not-used-by-this-spec',
    password_changed_at: new Date(),
  })
  for (const r of roles)
    await ds.query('INSERT INTO iam_user_roles (user_id, role_id) VALUES (?, ?)', [id, r])
  userIds.push(id)
  return (await signIn(app, PREFIX + name)).accessToken
}

beforeAll(async () => {
  const moduleRef = await Test.createTestingModule({ imports: [AppModule] }).compile()
  app = setupApp(moduleRef.createNestApplication<NestExpressApplication>({ logger: false }))
  await app.listen(0, '127.0.0.1')
  ds = app.get<DataSource>(getDataSourceToken())
  redis = app.get(REDIS)
  i18n = app.get(I18nService)
  await cleanRedis(redis)
  lastId = Number((await ds.query('SELECT COALESCE(MAX(id), 0) AS n FROM fs_storage'))[0].n)
  roleId = await insertRow(ds.manager, 'iam_role', {
    code: `${PREFIX}reader`,
    name: `${PREFIX}reader`,
    data_scope: 'all',
  })
  const browse = await findId(ds.manager, 'iam_menu', { perms: configPerms.browse })
  await ds.query('INSERT INTO iam_role_menus (role_id, menu_id) VALUES (?, ?)', [roleId, browse])
  tokens.admin = (await signIn(app)).accessToken
  tokens.reader = await user('reader', [roleId])
  tokens.plain = await user('plain', [])
})

afterAll(async () => {
  if (ds) {
    await ds.query('DELETE FROM fs_storage WHERE id > ?', [lastId])
    if (userIds.length) {
      await ds.query('DELETE FROM iam_user_roles WHERE user_id IN (?)', [userIds])
      await ds.query('DELETE FROM iam_user WHERE id IN (?)', [userIds])
    }
    await ds.query('DELETE FROM iam_role_menus WHERE role_id = ?', [roleId])
    await ds.query('DELETE FROM iam_role WHERE id = ?', [roleId])
  }
  if (redis) await cleanRedis(redis)
  await app?.close()
})

describe('CRUD', () => {
  it('create → 201 with the row (defaults filled, audit columns set); get returns it', async () => {
    const tag = unique()
    const res = await create(body(tag)).expect(201)
    const row = res.body.data
    expect(row).toMatchObject({
      id: expect.any(Number),
      ...body(tag),
      isPrimary: false,
      enabled: true,
      note: null,
    })
    expect(row).not.toHaveProperty('config')
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt)
    const got = await call('admin', 'get', `/${row.id}`).expect(200)
    expect(got.body.data).toEqual(row)
  })

  it('list: newest first by the sort whitelist, all live rows counted, paging, enabled equals', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const res = await list({ sort: '-id', pageSize: 3 })
    expect(idsOf(res)).toEqual([...ids].reverse())
    expect(res.body.data.total).toBe(await count())
    expect(idsOf(await list({ sort: '-id', page: 2, pageSize: 2 }))[0]).toBe(ids[0])
    const off = (await add(body(unique(), { enabled: false }))).id
    expect(idsOf(await list({ enabled: 'false', sort: '-id', pageSize: 1 }))).toEqual([off])
    expect(idsOf(await list({ enabled: 'true', sort: '-id', pageSize: 1 }))).toEqual([ids[2]])
  })

  it('list: text filters contain (LIKE wildcards literal) and combine with enabled', async () => {
    const tag = unique()
    for (const suffix of ['a', 'b', 'c']) await add(body(`${tag}-${suffix}`))
    await add(body(`${tag}-off`, { enabled: false }))
    await add(body(`${tag}_x`))

    const list = (query: object) => call('admin', 'get').query(query).expect(200)
    const keys = (res: request.Response) => res.body.data.items.map((r: { name: string }) => r.name)
    const res = await list({ name: `${tag}-`, enabled: 'true', sort: '-id' })
    expect(keys(res)).toEqual([`${tag}-c`, `${tag}-b`, `${tag}-a`])
    expect(res.body.data.total).toBe(3)
    expect(keys(await list({ name: tag, enabled: 'false' }))).toEqual([`${tag}-off`])
    // `%` and `_` in the filter are plain characters
    expect(keys(await list({ name: `${tag}_` }))).toEqual([`${tag}_x`])
    const page2 = await list({ name: `${tag}-`, sort: 'id', page: 2, pageSize: 2 })
    expect(keys(page2)).toEqual([`${tag}-c`, `${tag}-off`])
    expect(page2.body.data.total).toBe(4)
  })

  it('update takes the whole form; enabled toggles', async () => {
    const tag = unique()
    const { id } = await add(body(tag))
    await call('admin', 'put', `/${id}`, body(tag, { note: `${tag} renamed` })).expect(200)
    await call('admin', 'put', `/${id}/enabled`, { enabled: false }).expect(200)
    expect((await call('admin', 'get', `/${id}`)).body.data).toMatchObject({
      ...body(tag),
      note: `${tag} renamed`,
      enabled: false,
    })
  })

  it('a row PUT back as loaded (nulls included, as the edit form sends it) → 200, unchanged', async () => {
    const row = await add(body(unique()))
    const loaded = Object.fromEntries(FORM.map((f) => [f, row[f]]))
    await call('admin', 'put', `/${row.id}`, loaded).expect(200)
    expect((await call('admin', 'get', `/${row.id}`)).body.data).toMatchObject(loaded)
  })

  it('delete and batch delete (soft: the rows stay, marked deleted)', async () => {
    const ids: number[] = []
    for (let i = 0; i < 3; i++) ids.push((await add(body(unique()))).id)
    await call('admin', 'delete', `/${ids[0]}`).expect(200)
    await call('admin', 'post', '/batch-delete', { ids: ids.slice(1) }).expect(200)
    expect(
      await ds.query('SELECT id FROM fs_storage WHERE id IN (?) AND deleted_at IS NULL', [ids]),
    ).toEqual([])
    expect(await ds.query('SELECT id FROM fs_storage WHERE id IN (?)', [ids])).toHaveLength(3)
    await call('admin', 'get', `/${ids[0]}`).expect(404)
  })
})

describe('errors', () => {
  it('403 per permission: browse-only may list, not view/create/modify/delete; no perm → no list', async () => {
    const { id } = await add(body(unique()))
    await call('reader', 'get').expect(200)
    const forbidden = [
      call('reader', 'get', `/${id}`),
      call('reader', 'post', '', body(unique())),
      call('reader', 'put', `/${id}`, {}),
      call('reader', 'put', `/${id}/enabled`, { enabled: false }),
      call('reader', 'delete', `/${id}`),
      call('reader', 'post', '/batch-delete', { ids: [id] }),
      call('plain', 'get'),
    ]
    for (const res of await Promise.all(forbidden)) {
      expect(res.status).toBe(403)
      expect(res.body.code).toBe(Err.FORBIDDEN.code)
    }
  })

  it('400: invalid body / query / id, with translated field messages', async () => {
    const { id } = await add(body(unique()))
    const required = (lang: string, field: string) =>
      t(lang, 'validation.required', { field: label(lang, field) })
    expect(label('zh-CN', 'name')).not.toMatch(/^field\./)
    expect(label('en-US', 'name')).not.toMatch(/^field\./)
    const zh = await create({ ...body(unique()), name: '', note: 'x'.repeat(501) }).expect(400)
    expect(zh.body).toMatchObject({
      code: Err.VALIDATION_FAILED.code,
      msg: required('zh-CN', 'name'),
    })
    expect(zh.body.errors).toEqual([
      { path: 'name', msg: required('zh-CN', 'name') },
      {
        path: 'note',
        msg: t('zh-CN', 'validation.too_big.string', {
          field: label('zh-CN', 'note'),
          maximum: 500,
        }),
      },
    ])
    const { name: _, ...keyless } = body(unique())
    const en = await create(keyless).set('Accept-Language', 'en-US').expect(400)
    expect(en.body.errors).toEqual([{ path: 'name', msg: required('en-US', 'name') }])
    await call('admin', 'get').query({ sort: 'enabled' }).expect(400)
    await call('admin', 'put', `/${id}/enabled`, { enabled: 'no' }).expect(400)
    await call('admin', 'post', '/batch-delete', { ids: [] }).expect(400)
    await call('admin', 'get', '/abc').expect(400)
  })

  it('409 duplicate: a unique value already taken (create and update; case-insensitive)', async () => {
    const tag = unique()
    const taken = await add(body(tag))
    const other = await add(body(unique()))
    for (const res of [
      await create({ ...body(unique()), name: taken.name.toUpperCase() }),
      await call('admin', 'put', `/${taken.id}`, body(other.name)),
    ]) {
      expect(res.status).toBe(409)
      expect(res.body).toMatchObject({
        code: Err.DUPLICATE.code,
        msg: t('zh-CN', Err.DUPLICATE.key),
      })
    }
  })

  it('404: unknown ids for get, update, enabled, delete; a batch with one unknown id deletes nothing', async () => {
    const { id } = await add(body(unique()))
    for (const res of [
      await call('admin', 'get', `/${MISSING}`),
      await call('admin', 'put', `/${MISSING}`, body(unique())),
      await call('admin', 'put', `/${MISSING}/enabled`, { enabled: true }),
      await call('admin', 'delete', `/${MISSING}`),
      await call('admin', 'post', '/batch-delete', { ids: [id, MISSING] }),
    ]) {
      expect(res.status).toBe(404)
      expect(res.body.code).toBe(Err.NOT_FOUND.code)
    }
    await call('admin', 'get', `/${id}`).expect(200)
  })

  it('the same create submitted twice within 3 s → 429 (@Idempotent)', async () => {
    const tag = unique()
    await create(body(tag)).expect(201)
    const again = await create(body(tag)).expect(429)
    expect(again.body.code).toBe(Err.TOO_MANY_REQUESTS.code)
  })
})

describe('S3 secret target binding', () => {
  const s3Body = (over: object = {}) => ({
    ...body(unique()),
    driver: 's3',
    endpoint: 'https://s3.example.com',
    region: 'us-east-1',
    bucket: 'qw-files',
    accessKey: 'AKIDEXAMPLE',
    secretKey: 'original-storage-secret',
    forcePathStyle: true,
    publicDomain: null,
    ...over,
  })
  const stored = async (id: number) =>
    (await ds.query('SELECT * FROM fs_storage WHERE id = ?', [id]))[0]
  const targets = [
    ['endpoint', 'https://other.example.com'],
    ['bucket', 'other-bucket'],
    ['accessKey', 'OTHERACCESSKEY'],
  ] as const
  const keptSecrets = [
    ['missing', undefined],
    ['empty', ''],
    ['whitespace', ' \t\n '],
    ['mask', STORAGE_SECRET_MASK],
    ['padded mask', ` ${STORAGE_SECRET_MASK} `],
  ] as const

  it.each(
    targets.flatMap(([field, value]) =>
      keptSecrets.flatMap(([kind, secretKey]) =>
        ['zh-CN', 'en-US'].map((lang) => ({ field, value, kind, secretKey, lang })),
      ),
    ),
  )(
    '$field changed + $kind secret ($lang) → translated 422, entire row unchanged',
    async ({ field, value, secretKey, lang }) => {
      const form = s3Body()
      const { id } = await add(form)
      const before = await stored(id)
      const res = await call('admin', 'put', `/${id}`, {
        ...form,
        [field]: value,
        secretKey,
        name: unique(),
        note: 'must roll back',
        enabled: false,
      })
        .set('Accept-Language', lang)
        .expect(422)
      expect(t(lang, Err.STORAGE_SECRET_REQUIRED.key)).not.toBe(Err.STORAGE_SECRET_REQUIRED.key)
      expect(res.body).toMatchObject({
        code: 'C1010',
        msg: t(lang, Err.STORAGE_SECRET_REQUIRED.key),
      })
      expect(await stored(id)).toEqual(before)
    },
  )

  it.each(keptSecrets)(
    'unchanged target + %s secret → same cipher, other fields editable',
    async (_, secretKey) => {
      const form = s3Body()
      const { id } = await add(form)
      const before = await stored(id)
      await call('admin', 'put', `/${id}`, {
        ...form,
        endpoint: ` ${form.endpoint} `,
        bucket: ` ${form.bucket} `,
        accessKey: ` ${form.accessKey} `,
        secretKey,
        name: unique(),
        note: 'edited without rotating the secret',
        enabled: false,
        region: 'us-west-2',
        forcePathStyle: false,
        publicDomain: 'https://cdn.example.com',
      }).expect(200)
      const after = await stored(id)
      expect(after.config).toEqual({
        ...before.config,
        region: 'us-west-2',
        forcePathStyle: false,
        publicDomain: 'https://cdn.example.com',
      })
      expect(after).toMatchObject({ enabled: 0, note: 'edited without rotating the secret' })
      expect(after.name).not.toBe(before.name)
      expect((await call('admin', 'get', `/${id}`).expect(200)).body.data.secretKey).toBe(
        STORAGE_SECRET_MASK,
      )
    },
  )

  it.each(targets)(
    '%s changed + new secret → new decryptable cipher, masked detail',
    async (field, value) => {
      const form = s3Body()
      const { id } = await add(form)
      const before = await stored(id)
      await call('admin', 'put', `/${id}`, {
        ...form,
        [field]: value,
        secretKey: ' rotated-storage-secret ',
      }).expect(200)
      const after = await stored(id)
      expect(after.config[field]).toBe(value)
      expect(after.config.secretKey).not.toBe(before.config.secretKey)
      expect(app.get(SecretBox).decrypt(after.config.secretKey)).toBe('rotated-storage-secret')
      const detail = (await call('admin', 'get', `/${id}`).expect(200)).body.data
      expect(detail).toMatchObject({ [field]: value, secretKey: STORAGE_SECRET_MASK })
      expect(JSON.stringify(detail)).not.toContain('rotated-storage-secret')
      expect(JSON.stringify(detail)).not.toContain(after.config.secretKey)
    },
  )

  it('create still rejects empty secrets; update rejects non-string secrets', async () => {
    for (const secretKey of ['', ' \t\n ']) await create(s3Body({ secretKey })).expect(400)
    const form = s3Body()
    const { id } = await add(form)
    const before = await stored(id)
    for (const secretKey of [null, 123])
      await call('admin', 'put', `/${id}`, { ...form, secretKey }).expect(400)
    expect(await stored(id)).toEqual(before)
  })

  it('local edits work; driver-fixed and primary-lock guards still reject before writing', async () => {
    const local = await add(body(unique()))
    await call(
      'admin',
      'put',
      `/${local.id}`,
      body(local.name, { publicPrefix: '/assets' }),
    ).expect(200)
    expect((await stored(local.id)).config).toEqual({ publicPrefix: '/assets' })
    const localBefore = await stored(local.id)
    const switched = await call('admin', 'put', `/${local.id}`, s3Body()).expect(422)
    expect(switched.body.code).toBe(Err.STORAGE_DRIVER_FIXED.code)
    expect(await stored(local.id)).toEqual(localBefore)

    const form = s3Body()
    const { id } = await add(form)
    const switchedBack = await call('admin', 'put', `/${id}`, body(form.name)).expect(422)
    expect(switchedBack.body.code).toBe(Err.STORAGE_DRIVER_FIXED.code)
    const primary = (await ds.query('SELECT id FROM fs_storage WHERE is_primary = 1'))[0]
    try {
      await call('admin', 'put', `/${id}/primary`).expect(200)
      const before = await stored(id)
      const disabled = await call('admin', 'put', `/${id}`, {
        ...form,
        endpoint: 'https://other.example.com',
        secretKey: '',
        enabled: false,
      }).expect(422)
      expect(disabled.body.code).toBe(Err.STORAGE_PRIMARY_LOCKED.code)
      expect(await stored(id)).toEqual(before)
    } finally {
      await ds.query('UPDATE fs_storage SET is_primary = 0 WHERE id = ?', [id])
      if (primary) await ds.query('UPDATE fs_storage SET is_primary = 1 WHERE id = ?', [primary.id])
    }
  })

  it('S3 edit without permission → 403; missing row → 404', async () => {
    const form = s3Body()
    const { id } = await add(form)
    const before = await stored(id)
    const changed = { ...form, bucket: 'other-bucket', secretKey: '' }
    for (const who of ['reader', 'plain'] as const) {
      const res = await call(who, 'put', `/${id}`, changed).expect(403)
      expect(res.body.code).toBe(Err.FORBIDDEN.code)
    }
    expect(await stored(id)).toEqual(before)
    const missing = await call('admin', 'put', `/${MISSING}`, changed).expect(404)
    expect(missing.body.code).toBe(Err.NOT_FOUND.code)
  })

  it('compares the target read under the lock after a concurrent writer commits', async () => {
    const form = s3Body()
    const { id } = await add(form)
    const before = await stored(id)
    const writer = ds.createQueryRunner()
    const configs = app.get(StorageConfigService)
    const lock = configs.lockScopedIds.bind(configs)
    let locking = false
    const spy = vi.spyOn(configs, 'lockScopedIds').mockImplementationOnce((ids) => {
      locking = true
      return lock(ids)
    })
    let pending: Promise<request.Response> | undefined
    await writer.startTransaction()
    try {
      await writer.query('SELECT id FROM fs_storage WHERE id = ? FOR UPDATE', [id])
      // The request matches the old target, but must not reuse the next writer's secret there.
      pending = call('admin', 'put', `/${id}`, { ...form, secretKey: STORAGE_SECRET_MASK }).then(
        (r) => r,
      )
      await vi.waitFor(() => expect(locking).toBe(true), { timeout: 5000 })
      await writer.query('UPDATE fs_storage SET config = ? WHERE id = ?', [
        JSON.stringify({
          ...before.config,
          endpoint: 'https://other.example.com',
          secretKey: app.get(SecretBox).encrypt('concurrent-storage-secret'),
        }),
        id,
      ])
      const [committed] = await writer.query('SELECT * FROM fs_storage WHERE id = ?', [id])
      await writer.commitTransaction()
      const res = await pending
      expect(res.status).toBe(422)
      expect(res.body.code).toBe(Err.STORAGE_SECRET_REQUIRED.code)
      expect(await stored(id)).toEqual(committed)
    } finally {
      if (writer.isTransactionActive) await writer.rollbackTransaction()
      await writer.release()
      await pending
      spy.mockRestore()
    }
  })
})

it('@ActionLog: every write leaves a row with domain storage.config, its verb and the id', async () => {
  const trace = `${PREFIX}${process.pid}-`
  const created = await create(body(unique())).set('X-Request-Id', `${trace}c`).expect(201)
  const { id } = created.body.data
  await call('admin', 'put', `/${id}`, created.body.data).set('X-Request-Id', `${trace}u`)
  await call('admin', 'put', `/${id}/enabled`, { enabled: false }).set('X-Request-Id', `${trace}e`)
  await call('admin', 'delete', `/${id}`).set('X-Request-Id', `${trace}d`)
  await call('admin', 'post', '/batch-delete', { ids: [MISSING] }).set('X-Request-Id', `${trace}b`)
  const expected: [string, object][] = [
    ['c', { verb: 'create', biz_id: String(id), ok: 1 }],
    ['u', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['e', { verb: 'modify', biz_id: String(id), ok: 1 }],
    ['d', { verb: 'remove', biz_id: String(id), ok: 1 }],
    ['b', { verb: 'remove', biz_id: null, ok: 0, error_msg: Err.NOT_FOUND.key }],
  ]
  for (const [suffix, row] of expected)
    expect(await logOf(ds, `${trace}${suffix}`)).toMatchObject({
      domain: 'storage.config',
      username: 'admin',
      ...row,
    })
})

it('Swagger documents every route', async () => {
  const doc = (await request(app.getHttpServer()).get('/api/docs-json').expect(200)).body
  expect(
    Object.keys(doc.paths)
      .filter((p) => p.startsWith(URL))
      .sort(),
  ).toEqual([
    URL,
    `${URL}/batch-delete`,
    `${URL}/{id}`,
    `${URL}/{id}/enabled`,
    `${URL}/{id}/primary`,
    `${URL}/{id}/test`,
  ])
  expect(
    doc.paths[URL].get.responses['200'].content['application/json'].schema.properties.data,
  ).toMatchObject({ properties: { items: { type: 'array' }, total: { type: 'integer' } } })
})
